import CryptoKit
import UIKit
import XCTest
@testable import ZTransfer

final class PhotoNp3RenderingTests: XCTestCase {
    private let finishing = LUTAdjustments(contrast: 17, saturation: -23, highlights: 31, shadows: -19)

    /// Generated by the unchanged Android renderer, not by a second Swift
    /// implementation. The retained oracle runner documents every input.
    func testAll1648ConfigurationsMatchCurrentAndroidByteForByte() throws {
        let url = try XCTUnwrap(Bundle(for: Self.self).resourceURL)
            .appendingPathComponent("PictureControlFixtures/np3-renderer-oracle.txt")
        let lines = try String(contentsOf: url, encoding: .utf8).split(separator: "\n")
        XCTAssertEqual(lines.count, 1_648)
        let pixels = Self.colors()
        for line in lines {
            let fields = line.split(separator: "|")
            guard fields.count == 7, let id = Int(fields[1]), let mode = Int(fields[2]),
                  let strength = Int(fields[3]) else { return XCTFail("Invalid oracle row") }
            let recipe: PhotoNp3Parameters = fields[0] == "C"
                ? .classic(try classic(try XCTUnwrap(ClassicNp3Style(rawValue: id)), mode: mode))
                : .flexible(flexible(id))
            let engine = Np3FilterEngine(parameters: recipe, intensityPercent: strength,
                                         adjustments: fields[5] == "1" ? finishing : .init(),
                                         preserveAlpha: fields[4] == "1")
            var bytes = Data()
            for pixel in pixels {
                let output = engine.filterPixel(pixel)
                bytes.append(contentsOf: [UInt8(output >> 24), UInt8(output >> 16 & 255),
                                          UInt8(output >> 8 & 255), UInt8(output & 255)])
            }
            let hash = SHA256.hash(data: bytes).map { String(format: "%02x", $0) }.joined()
            XCTAssertEqual(hash, String(fields[6]), fields.prefix(6).joined(separator: "|"))
        }
    }

    func testNeutralGradingHasNoCompiledTables() {
        XCTAssertNil(CompiledNp3ColorGrading(grading: .init()))
        XCTAssertNil(CompiledNp3ColorGrading(grading: .init(highlights: .init(hue: 360),
            midtones: .init(hue: 120), shadows: .init(hue: 240), blending: 100, balance: -100)))
    }

    func testGradingRegionsBalanceBlendAndHueWrap() throws {
        let grade = Np3ColorGrading(highlights: .init(hue: 0, chroma: 80),
            midtones: .init(hue: 120, chroma: 80), shadows: .init(hue: 240, chroma: 80), blending: 0)
        let effect = try XCTUnwrap(CompiledNp3ColorGrading(grading: grade))
        for (gray, channel) in [(0x20, 2), (0x80, 1), (0xe0, 0)] {
            let rgb = Self.channels(effect.apply(UInt32(gray * 0x010101)))
            for other in 0..<3 where other != channel { XCTAssertGreaterThan(rgb[channel], rgb[other]) }
        }
        XCTAssertEqual(effect.apply(0), 0); XCTAssertEqual(effect.apply(0xffffff), 0xffffff)
        var warm = grade; warm.midtones = .init(); warm.balance = 100
        var cool = warm; cool.balance = -100
        let a = Self.channels(try XCTUnwrap(CompiledNp3ColorGrading(grading: warm)).apply(0x808080))
        let b = Self.channels(try XCTUnwrap(CompiledNp3ColorGrading(grading: cool)).apply(0x808080))
        XCTAssertGreaterThan(a[0], a[2]); XCTAssertGreaterThan(b[2], b[0])
        var wide = grade; wide.blending = 100
        XCTAssertNotEqual(effect.apply(0x606060), try XCTUnwrap(CompiledNp3ColorGrading(grading: wide)).apply(0x606060))
        let zero = Np3ColorGrading(midtones: .init(hue: 0, chroma: 100, brightness: 100))
        var full = zero; full.midtones.hue = 360
        XCTAssertEqual(try XCTUnwrap(CompiledNp3ColorGrading(grading: zero)).apply(0x7a8496),
                       try XCTUnwrap(CompiledNp3ColorGrading(grading: full)).apply(0x7a8496))
    }

    func testTintPreservesLuminanceAndGrayRampHasNoBandJumps() throws {
        let grade = Np3ColorGrading(highlights: .init(hue: 45, chroma: 100),
            midtones: .init(hue: 120, chroma: -100), shadows: .init(hue: 240, chroma: 100), blending: 100, balance: 100)
        let effect = try XCTUnwrap(CompiledNp3ColorGrading(grading: grade))
        for color in Self.colors(count: 4096) {
            func luma(_ color: UInt32) -> Float {
                let rgb = Self.channels(color)
                return rgb[0] * 0.2126 + rgb[1] * 0.7152 + rgb[2] * 0.0722
            }
            XCTAssertLessThanOrEqual(abs(luma(color) - luma(effect.apply(color))), 1)
        }
        for index in 1...9 {
            let compiled = try XCTUnwrap(CompiledNp3ColorGrading(grading: flexible(index).colorGrading))
            var before = Self.channels(compiled.apply(0))
            for value in 1...255 {
                let after = Self.channels(compiled.apply(UInt32(value * 0x010101)))
                for c in 0..<3 { XCTAssertLessThanOrEqual(abs(after[c] - before[c]), 8) }
                before = after
            }
        }
    }

    func testClassicAutomaticAndCurveOwnership() throws {
        let automatic = try ClassicNp3FilterParameters(base: .auto, contrastQuarter: -128,
            brightnessQuarter: 0, saturationQuarter: -128, hueQuarter: 0, filterEffect: 0,
            toningEffect: 0, toningDensityQuarter: 16, effectLevel: 100, toneCurve: nil)
        let engine = Np3FilterEngine(parameters: .classic(automatic), intensityPercent: 100)
        for color in Self.colors() { XCTAssertEqual(engine.filterPixel(color), color) }
        let curve = (0...256).map { UInt16(4096 + $0 * 96) }
        func recipe(_ contrast: Int, _ brightness: Int) throws -> PhotoNp3Parameters {
            .classic(try .init(base: .standard, contrastQuarter: contrast, brightnessQuarter: brightness,
                saturationQuarter: 0, hueQuarter: 0, filterEffect: 0, toningEffect: 0,
                toningDensityQuarter: 16, effectLevel: 100, toneCurve: curve))
        }
        let a = Np3FilterEngine(parameters: try recipe(0, 0), intensityPercent: 100)
        let b = Np3FilterEngine(parameters: try recipe(12, -6), intensityPercent: 100)
        for color in Self.colors() { XCTAssertEqual(a.filterPixel(color), b.filterPixel(color)) }
        XCTAssertEqual(a.filterPixel(0xff000000) & 255, 32)
        XCTAssertEqual(a.filterPixel(0xffffffff) & 255, 223)
    }

    func testCreativeEffectZeroPreservesDevelopedSource() throws {
        for base in ClassicNp3Style.allCases where base.isCreative {
            let recipe = try ClassicNp3FilterParameters(base: base, contrastQuarter: 0,
                brightnessQuarter: 0, saturationQuarter: 0, hueQuarter: 0, filterEffect: 0,
                toningEffect: 0, toningDensityQuarter: 16, effectLevel: 0, toneCurve: nil)
            let engine = Np3FilterEngine(parameters: .classic(recipe), intensityPercent: 100)
            for color in Self.colors() { XCTAssertEqual(engine.filterPixel(color), color, "\(base)") }
        }
    }

    func testEachGradingRegionBrightnessWorksWithoutTint() throws {
        for region in 0..<3 {
            let gray = [0x303030, 0x808080, 0xd0d0d0][region]
            for amount in [-100, 100] {
                var grade = Np3ColorGrading()
                let control = Np3ColorGradingRegion(brightness: amount)
                switch region {
                case 0: grade.shadows = control
                case 1: grade.midtones = control
                default: grade.highlights = control
                }
                let result = Self.channels(try XCTUnwrap(CompiledNp3ColorGrading(grading: grade)).apply(UInt32(gray)))
                XCTAssertEqual(result[0], result[1]); XCTAssertEqual(result[1], result[2])
                if amount > 0 { XCTAssertGreaterThan(result[0], Float(gray & 255)) }
                else { XCTAssertLessThan(result[0], Float(gray & 255)) }
            }
        }
    }

    func testFinishingIsOnceAfterStrengthAndKeepsTransparentPixels() throws {
        let recipes: [PhotoNp3Parameters] = [.classic(try classic(.sepia, mode: 1)), .flexible(flexible(5))]
        for recipe in recipes {
            for strength in [2, 80, 100] {
                let plain = Np3FilterEngine(parameters: recipe, intensityPercent: strength)
                let finished = Np3FilterEngine(parameters: recipe, intensityPercent: strength, adjustments: finishing)
                for color in Self.colors() {
                    XCTAssertEqual(finished.filterPixel(color),
                        LUTColorPipeline.apply(plain.filterPixel(color), adjustments: finishing, preserveAlpha: true))
                }
                XCTAssertEqual(finished.filterPixel(0x00123456), 0x00123456)
            }
        }
    }

    func testCancellationStopsBothNewPixelPathsAtBoundedBatch() throws {
        for recipe in [PhotoNp3Parameters.classic(try classic(.carbon, mode: 1)), .flexible(flexible(5))] {
            let engine = Np3FilterEngine(parameters: recipe, intensityPercent: 80)
            var pixels = [UInt32](repeating: 0xff896432, count: 8193), probes = 0
            XCTAssertThrowsError(try engine.filterPixels(&pixels, isCancelled: { probes += 1; return probes == 2 })) {
                XCTAssertTrue($0 is CancellationError)
            }
            XCTAssertEqual(probes, 2)
            XCTAssertTrue(pixels[4096...].allSatisfy { $0 == 0xff896432 })
            XCTAssertTrue(pixels[..<4096].allSatisfy { $0 == engine.filterPixel(0xff896432) })
        }
    }

    func testTypedBitmapSerialAndPreviewMatchAndPreserveSource() throws {
        let source = try image(width: 512, height: 513)
        let before = try bytes(source)
        for recipe in [PhotoNp3Parameters.classic(try classic(.pink, mode: 1)), .flexible(flexible(5))] {
            let original = try Np3BitmapFilter.apply(source, parameters: recipe, intensityPercent: 80,
                adjustments: finishing, execution: .original)
            let preview = try Np3BitmapFilter.apply(source, parameters: recipe, intensityPercent: 80,
                adjustments: finishing, execution: .preview)
            XCTAssertEqual(try bytes(original), try bytes(preview))
            XCTAssertEqual(original.width, 512); XCTAssertEqual(original.height, 513)
        }
        XCTAssertEqual(try bytes(source), before)
    }

    func testApplicationFilterPathActuallyAppliesFinishing() throws {
        let cg = try image(width: 16, height: 8), source = UIImage(cgImage: cg)
        let preset = TestPhotoFilterCatalog.np3Presets[0]
        var settings = PhotoEffectsSettings()
        settings.photoFilterEnabled = true
        settings.selectedFilter = testPhotoFilterSelection(preset: .init(id: preset.id, name: preset.name),
            intensityPercent: 80, lutAdjustments: finishing)
        let output = try PhotoEffectsRenderer.render(source, settings: settings)
        let expected = try Np3BitmapFilter.apply(cg, parameters: preset.parameters,
            intensityPercent: 80, adjustments: finishing, execution: .original)
        XCTAssertEqual(try bytes(XCTUnwrap(output.cgImage)), try bytes(expected))
        let noFinishing = try Np3BitmapFilter.apply(cg, parameters: preset.parameters, intensityPercent: 80)
        XCTAssertNotEqual(try bytes(expected), try bytes(noFinishing))
    }

    private func classic(_ base: ClassicNp3Style, mode: Int) throws -> ClassicNp3FilterParameters {
        switch mode {
        case 0: return try .init(base: base, contrastQuarter: 0, brightnessQuarter: 0, saturationQuarter: 0,
            hueQuarter: 0, filterEffect: 0, toningEffect: 0, toningDensityQuarter: 16, effectLevel: 100, toneCurve: nil)
        case 1: return try .init(base: base, contrastQuarter: -3, brightnessQuarter: 1, saturationQuarter: 2,
            hueQuarter: -1, filterEffect: base.isMonochrome ? 3 : 0, toningEffect: base.isMonochrome ? 3 : 0,
            toningDensityQuarter: 20, effectLevel: 50, toneCurve: nil)
        default: return try .init(base: base, contrastQuarter: 12, brightnessQuarter: -6, saturationQuarter: -5,
            hueQuarter: 3, filterEffect: 4, toningEffect: 9, toningDensityQuarter: 28, effectLevel: 20,
            toneCurve: (0...256).map { 4096 + $0 * 96 })
        }
    }

    private func flexible(_ index: Int) -> Np3FilterParameters {
        let grade: Np3ColorGrading = index == 0 ? .init() : .init(highlights: .init(hue: 45, chroma: 100, brightness: 50),
            midtones: .init(hue: 120, chroma: -100, brightness: -50), shadows: .init(hue: 240, chroma: 100, brightness: 50),
            blending: [0, 50, 100][(index - 1) / 3], balance: [-100, 0, 100][(index - 1) % 3])
        return .init(contrast: -20, highlights: 10, shadows: -7, whites: 13, blacks: -9, saturation: 24,
            colorBands: Np3FilterParameters.colorBandCenters.enumerated().map { i, c in
                .init(centerDegrees: c, hue: i * 17 - 50, chroma: i * 12 - 30, brightness: i * 9 - 20)
            }, toneCurve: index % 2 == 0 ? nil : (0...256).map { min(32767, $0 * 128) }, colorGrading: grade)
    }

    private static func colors(count: Int = 512) -> [UInt32] {
        var seed: UInt32 = 0x12345678
        return (0..<count).map { _ in seed = seed &* 1664525 &+ 1013904223; return seed }
            + [0, 0xffffffff, 0x00123456, 0x7f123456, 0xff000000, 0xff808080]
    }
    private static func channels(_ rgb: UInt32) -> [Float] { [Float(rgb >> 16 & 255), Float(rgb >> 8 & 255), Float(rgb & 255)] }

    private func image(width: Int, height: Int) throws -> CGImage {
        let palette: [UInt8] = [160, 80, 40, 255, 40, 160, 100, 255, 48, 32, 16, 128, 0, 0, 0, 0]
        let data = Data((0..<(width * height * 4)).map { palette[$0 % palette.count] })
        let provider = try XCTUnwrap(CGDataProvider(data: data as CFData))
        return try XCTUnwrap(CGImage(width: width, height: height, bitsPerComponent: 8, bitsPerPixel: 32,
            bytesPerRow: width * 4, space: XCTUnwrap(CGColorSpace(name: CGColorSpace.sRGB)),
            bitmapInfo: [.byteOrder32Big, CGBitmapInfo(rawValue: CGImageAlphaInfo.premultipliedLast.rawValue)],
            provider: provider, decode: nil, shouldInterpolate: false, intent: .defaultIntent))
    }
    private func bytes(_ image: CGImage) throws -> Data {
        // UIKit's final canvas can be BGRA while the NP3 adapter is RGBA.
        // Compare exact color bytes in one sRGB premultiplied layout, not raw
        // provider storage with unrelated byte order or scanline padding.
        let context = try XCTUnwrap(CGContext(data: nil, width: image.width, height: image.height,
            bitsPerComponent: 8, bytesPerRow: image.width * 4,
            space: XCTUnwrap(CGColorSpace(name: CGColorSpace.sRGB)),
            bitmapInfo: CGBitmapInfo.byteOrder32Big.rawValue | CGImageAlphaInfo.premultipliedLast.rawValue))
        context.setBlendMode(.copy)
        context.draw(image, in: CGRect(x: 0, y: 0, width: image.width, height: image.height))
        return Data(bytes: try XCTUnwrap(context.data), count: image.width * image.height * 4)
    }
}
